INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33403$nota-0141$m33403$, $m33404$Training and Racing with a Power Meter.pdf$m33404$, $m33405$450$m33405$, $m33406$ALL LEVELS: KITCHEN SINK. Many of the rides work multiple energy systems at once, yet there is typically emphasis on one system. The rides that follow throw in 'everything but the kitchen sink.' They are challenging workouts and a good test of overall fatigue resistance.$m33406$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33407$nota-0141$m33407$, $m33408$nota-0079$m33408$, $m33409$complementa$m33409$, $m33410$formato de treino desenhado especificamente para testar a Stamina/resistência à fadiga (nota-0079) através do acúmulo de múltiplos sistemas na mesma sessão$m33410$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33411$nota-0142$m33411$, $m33412$Training and Racing with a Power Meter.pdf$m33412$, $m33413$454$m33413$, $m33414$PYRAMID WORKOUTS. P-W1 Pyramid Intervals... begin the pyramid: 4 minutes at upper FTP, rest for 2 minutes at Endurance pace; 3 minutes at VO2max, rest for 2 minutes at Endurance pace; 2 minutes at Anaerobic Capacity, rest for 2 minutes at Endurance pace; 1 minute maximum effort, 2 minutes rest at Endurance pace. Then come back down the pyramid... 2 minutes at Anaerobic Capacity; 3 minutes at VO2max; 4 minutes at lower FTP.$m33414$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33415$nota-0142$m33415$, $m33416$nota-0048$m33416$, $m33417$pre-requisito$m33417$, $m33418$usa os Níveis de Coggan (nota-0048) como degraus da pirâmide de intensidade$m33418$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33419$nota-0187$m33419$, $m33420$Manual treinamento.pdf$m33420$, $m33421$119$m33421$, $m33422$Estudos demonstram benefícios relacionados a: economia de pedalada; potência máxima; sprint; resistência à fadiga; prevenção de lesões... O objetivo não consiste em desenvolver hipertrofia máxima. O foco está na melhora da capacidade neuromuscular e da produção de força específica.$m33422$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33423$nota-0187$m33423$, $m33424$nota-0179$m33424$, $m33425$complementa$m33425$, $m33426$o treinamento de força é citado como um dos mecanismos capazes de melhorar a economia de pedalada definida na nota-0179$m33426$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33427$nota-0199$m33427$, $m33428$Manual treinamento.pdf$m33428$, $m33429$168$m33429$, $m33430$Sessões voltadas para a base aeróbia... Exemplo: 3h30 a 5h em Zona 2... Sessões voltadas para o limiar... Exemplos: 2 × 20 minutos; 3 × 15 minutos; 4 × 10 minutos.$m33430$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33431$nota-0199$m33431$, $m33432$Manual treinamento.pdf$m33432$, $m33433$169$m33433$, $m33434$Sessões de VO₂máx... Exemplos clássicos: 5 × 5 minutos; 6 × 4 minutos; 4 × 8 minutos; 30/30 segundos... Sessões anaeróbias... Exemplos: 8 × 1 minuto; 10 × 30 segundos; sprints repetidos.$m33434$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33435$nota-0199$m33435$, $m33436$Manual treinamento.pdf$m33436$, $m33437$170$m33437$, $m33438$Sessões neuromusculares... Exemplos: sprints de 6 a 12 segundos; acelerações; arrancadas. O foco está na qualidade. Nunca no volume.$m33438$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33439$nota-0199$m33439$, $m33440$nota-0140$m33440$, $m33441$complementa$m33441$, $m33442$catálogo alternativo de estruturas de sessão por objetivo, complementar (não conflitante) ao catálogo de treinos do apêndice do Livro 1 (nota-0140)$m33442$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33443$nota-0199$m33443$, $m33444$nota-0022$m33444$, $m33445$pre-requisito$m33445$, $m33446$as intensidades-alvo de cada tipo de sessão (Zona 2, LT2/FTP, VO2max) mapeiam para os níveis de %FTP da tabela de Coggan (nota-0022)$m33446$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33447$nota-0220$m33447$, $m33448$VO2 Max Essentials_Final.pdf$m33448$, $m33449$44$m33449$, $m33450$a systematic review and meta-analysis published in 2015 concluded that, while both moderate-intensity and high-intensity training can elicit improvements in VO2 max, high-intensity training is more effective. Specifically, in healthy adults, moderate-intensity training improves VO2 max by 4.9 ml/kg/min, while HIIT improves it by 5.5 ml/kg min... high-intensity outperforms moderate-intensity by 1.2 ml/kg/min. [Milanović Z, Sporiš G, Weston M. Sports Med. 2015;45(10):1469-1481.]$m33450$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33451$nota-0220$m33451$, $m33452$VO2 Max Essentials_Final.pdf$m33452$, $m33453$45$m33453$, $m33454$These effects seem to be modified by factors such as the length of repetitions performed during HIIT (longer reps are more effective), age of participants (older participants benefit more), the duration of the training intervention (longer is better), the work:rest ratio (greater work:rest is more beneficial), and baseline fitness levels (participants with lower baseline fitness improve more).$m33454$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33455$nota-0220$m33455$, $m33456$nota-0042$m33456$, $m33457$complementa$m33457$, $m33458$fornece evidência de meta-análise (não estudo único) reforçando a priorização de intervalados de alta intensidade para estímulo de VO2máx já registrada na nota-0042 do Livro 1$m33458$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33459$nota-0220$m33459$, $m33460$nota-0199$m33460$, $m33461$complementa$m33461$, $m33462$citada no corpo da nota como o catálogo de sessões do Manual que operacionaliza a recomendação de priorizar intervalados — link estrutural ausente até auditoria de 2026-08-02$m33462$)
